// Geocode simples via Google Maps (opcional) — aqui retorna endereço bruto.
// Em produção: trocar por HTTP Request para Google Geocoding API e setar lat/lng.
const p = $json.pedido;
return [{ json: { ...p, pickup: { address: $vars.LOJA_ENDERECO, lat: Number($vars.LOJA_LAT), lng: Number($vars.LOJA_LNG) }, dropoff: { address: p.endereco, lat: p.endereco_lat, lng: p.endereco_lng } } }];

// Normaliza resposta de cada provider
const p = $vars.MOTOBOY_PROVIDER;
const r = $json;
let out = { provider: p, order_id: null, tracking_url: null, fee: null, status: 'REQUESTED', raw: r };
if (p==='lalamove') { out.order_id = r.data?.orderId; out.tracking_url = r.data?.shareLink; out.fee = Number(r.data?.priceBreakdown?.total||0); }
else if (p==='uber_direct') { out.order_id = r.id; out.tracking_url = r.tracking_url; out.fee = Number(r.fee/100||0); }
else if (p==='loggi') { out.order_id = String(r.pk||r.id||''); out.tracking_url = r.tracking_url; out.fee = Number(r.estimated_price||0); }
else { out.provider = 'manual'; out.status = 'REQUESTED_MANUAL'; }
return [{ json: out }];

// Normaliza webhook de cada provider para: {order_id, status, driver:{name,phone}}
const b = $json.body || {};
const provider = $json.headers?.['x-provider'] || b.provider || $vars.MOTOBOY_PROVIDER;
let out = { provider, order_id: null, status: null, driver_name: null, driver_phone: null, raw: b };
if (provider==='lalamove') { out.order_id=b.data?.orderId; out.status=b.data?.status; out.driver_name=b.data?.driverName; out.driver_phone=b.data?.driverPhone; }
else if (provider==='uber_direct') { out.order_id=b.data?.id; out.status=b.status; out.driver_name=b.data?.courier?.name; out.driver_phone=b.data?.courier?.phone_number; }
else if (provider==='loggi') { out.order_id=String(b.order_id); out.status=b.status; }
return [{ json: out }];
